import { processBatch, classifySignal } from './pb';

const raw = {
  readings: [
    { channel: 'A', unit: 'mV', value: 100, at: 0 },
    { channel: 'B', unit: 'V', value: 1, at: 1 },
    { channel: 'C', unit: 'uV', value: 250000, at: 2 },
    { channel: 'A', unit: 'mV', value: 950, at: 3 },
    { channel: 'D', unit: 'mV', value: -5, at: 4 },
    { channel: 'A', unit: 'mV', value: 500, at: 5 },
  ],
};
console.log(JSON.stringify(processBatch(raw)));

// invalid cases
console.log(JSON.stringify(processBatch(null)));
console.log(JSON.stringify(processBatch(5)));
console.log(JSON.stringify(processBatch({})));
console.log(JSON.stringify(processBatch({ readings: [] })));
console.log(JSON.stringify(processBatch({ readings: [1,2,3] })));
console.log(JSON.stringify(processBatch({ readings: [{ channel:'', unit:'mV', value:1, at:0 }] })));
console.log(JSON.stringify(processBatch({ readings: [{ channel:'A', unit:'nope', value:1, at:0 }] })));
console.log(JSON.stringify(processBatch({ readings: [{ channel:'A', unit:'mV', value:1.5, at:0 }] })));
console.log(JSON.stringify(processBatch({ readings: [{ channel:'A', unit:'mV', value:1, at:-1 }] })));
console.log(JSON.stringify(processBatch({ readings: [{ channel:'A', unit:'mV', value:'x', at:0 }] })));

// boundary classify
for (const v of [-1, 0, 49, 50, 199, 200, 599, 600, 899, 900, 1000]) {
  console.log(v, classifySignal(v));
}
