function normalizeValue(unit: string, value: number): number {
  if (unit === "V") {
    return value * 1000;
  }
  if (unit === "uV") {
    return Math.trunc(value / 1000);
  }
  return value;
}

edits.newText:
function normalizeValue(unit: string, value: number): number {
  switch (unit) {
    case "V":
      return value * 1000;
    case "uV":
      return Math.trunc(value / 1000);
    default:
      return value;
  }
}

