function classifySignal(millivolts: number): string {
  if (millivolts < 0) {
    return "negative";
  }
  if (millivolts < THRESHOLD_IDLE) {
    return "standby";
  }
  if (millivolts < THRESHOLD_ACTIVE) {
    return "idle";
  }
  if (millivolts < THRESHOLD_LOADED) {
    return "active";
  }
  if (millivolts < THRESHOLD_CRITICAL) {
    return "loaded";
  }
  return "critical";
}

