function normalizeValue(unit: string, value: number): number {
  switch (unit) {
    case "V":
      return value * 1000;
    case "uV":
      return Math.trunc(value / 1000);
    default:
      return value;
  }
}

edits.oldText:
function classifySignal(millivolts: number): string {
  if (millivolts >= 0 && millivolts < 50) {
    return "standby";
  }
  if (millivolts >= 50 && millivolts < 200) {
    return "idle";
  }
  if (millivolts >= 200 && millivolts < 600) {
    return "active";
  }
  if (millivolts >= 600 && millivolts < 900) {
    return "loaded";
  }
  if (millivolts >= 900) {
    return "critical";
  }
  return "negative";
}

